const reqs = network.requests({ path: '/api/cart' });
const getReq = reqs.filter(r => r.method === 'GET').slice(-1)[0];
const postReq = reqs.filter(r => r.method === 'POST').slice(-1)[0];
const getBody = JSON.parse(getReq.responseBody);
const postBody = JSON.parse(postReq.responseBody);
const getQty = (getBody.items.find(item => item.id === 'p1') || { qty: 0 }).qty;
const postQty = (postBody.items.find(item => item.id === 'p1') || { qty: 0 }).qty;
return postQty - getQty;

const reqs = network.requests({ path: '/api/cart' });
const getReq = reqs.filter(r => r.method === 'GET').slice(-1)[0];
const postReq = reqs.filter(r => r.method === 'POST').slice(-1)[0];
const getBody = JSON.parse(getReq.responseBody);
const postBody = JSON.parse(postReq.responseBody);
return postBody.items[0].qty - getBody.items[0].qty;

